head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf70040";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf70040.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.tx_fn_searchKeywrdListDtl();
        $('.sort a').removeClass('active');
        $c.util.getComponent('all').addClass('active');

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf70040.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_keywrdNm_onkeydown
 * @description ipt_keywrdNm 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_keywrdNm_onkeydown = async function(e){
    try {
        await scwin.searchKey();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf70040.ipt_keywrdNm_onkeydown' }); }
};

