///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchKeywrdListDtl
 * @description search Keywrd List Dtl 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchKeywrdListDtl = async function () {
    const sbmOptions = {
        id: "tx_fn_searchKeywrdListDtl",
        method: "post",
        action: "/ods/integsrch.do",
        ref: "dma_searchKeywrdListDtlReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name searchKey
 * @description search Key 처리
 * @returns {void}
 * @hidden N
 */
scwin.searchKey = async function () {
    if (event.keyCode === 13) {
        await scwin.tx_fn_searchKeywrdListDtl();
        $('.sort a').removeClass('active');
        $c.util.getComponent('all').addClass('active');
    }
};

/**
 * @method
 * @name moveKeywrdList
 * @description move Keywrd List 처리
 * @returns {void}
 * @hidden N
 */
scwin.moveKeywrdList = async function () {
    await scwin.tx_fn_searchKeywrdListDtl("", true);
};

/**
 * @method
 * @name setParetKeywrd
 * @description set Paret Keywrd 처리
 * @param {*} keywrd keywrd
 * @returns {void}
 * @hidden N
 */
scwin.setParetKeywrd = function (keywrd) {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame
    $c.win.getParent().fn_SetKeywrd(keywrd);
    $c.win.closePopup();
};

/**
 * @method
 * @name clickKeyword
 * @description click Keyword 처리
 * @param {*} ele ele
 * @returns {void}
 * @hidden N
 */
scwin.clickKeyword = function (ele) {
    $('.sort a').on('click', function() {
            if ($(this).hasClass('active')) {
                return false;
            }
            $('.sort a').removeClass('active');
            $(this).addClass('active');
    });
};
// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
